#!/bin/sh
# Synthetic suspicious fixture: a spoofed ";base64," prefix in front of a
# gzip payload (issue #36 review) — no real "data:" mime precedes it, so the
# content-validated carrier check doesn't recognize it as a data URI, and the
# decoded bytes don't carry any known magic either way.
P=";base64,"
echo "${P#*,}" | base64 -d | gunzip | sh
